# builder/gen_ch16_p2.py
# -*- coding: utf-8 -*-

exercises = [{'num': 34, 'title': 'Удаление дубликатов с сохранением порядка: Unique[T comparable]', 'task': 'Используйте дженерики для создания функции `Unique[T comparable](s []T) []T`, которая удаляет дубликаты из слайса с сохранением порядка.', 'theory': 'Удаление дубликатов с сохранением порядка (Stable Deduplication) использует множество `seen := make(map[T]struct{})`. Ограничение `T comparable` необходимо, чтобы тип `T` мог служить ключом мапы. Алгоритмическая сложность: время $O(N)$, память $O(K)$.', 'step_by_step': '1. Объявим `Unique[T comparable](s []T) []T`.\n2. Создадим мапу `seen := make(map[T]struct{})` и срез `result := make([]T, 0, len(s))`.\n3. Для каждого элемента проверим `if _, ok := seen[v]; !ok`: добавим в `seen` и в `result`.\n4. В `main` протестируем на слайсе чисел и строк.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Unique[T comparable](s []T) []T {\n\tseen := make(map[T]struct{})\n\tresult := make([]T, 0, len(s))\n\tfor _, v := range s {\n\t\tif _, ok := seen[v]; !ok {\n\t\t\tseen[v] = struct{}{}\n\t\t\tresult = append(result, v)\n\t\t}\n\t}\n\treturn result\n}\n\nfunc main() {\n\tnums := []int{1, 2, 2, 3, 4, 3, 5, 1, 6}\n\tfmt.Println("Уникальные числа:", Unique(nums))\n\n\ttags := []string{"go", "docker", "k8s", "go", "grpc", "docker"}\n\tfmt.Println("Уникальные теги: ", Unique(tags))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Уникальные числа: [1 2 3 4 5 6]\n# Уникальные теги:  [go docker k8s grpc]'}], 'under_the_hood': 'Мапа `seen` аллоцирует бакеты под размер типа `T`. При $N < 16$ линейный скан слайса может быть быстрее, но для произвольных $N$ мапа дает гарантированное $O(N)$.', 'pitfalls': 'Помните, что `Unique` создает новый слайс. Для in-place удаления в отсортированном срезе лучше использовать `slices.Compact`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Unique от slices.Compact в Go 1.21+?»\n**Ответ:** `slices.Compact` удаляет только последовательные дубликаты (требует сортировки) с $O(1)$ памяти, а `Unique` работает с неотсортированными данными за $O(N)$ памяти.'}, {'num': 35, 'title': 'Встраивание интерфейсов в constraints: OrderedStringer', 'task': 'Создай constraint через embedding:\n```go\ntype OrderedStringer interface {\n    cmp.Ordered\n    fmt.Stringer\n}\n```\nНапиши `PrintSorted[T OrderedStringer](items []T)`, которая сортирует (используя `<`) и выводит через `String()`.', 'theory': 'Интерфейс-ограничение может объединять требования к типам (`cmp.Ordered`) и набору методов (`fmt.Stringer`) через Embedding. Тип `T` обязан быть упорядоченным числом/строкой И иметь метод `String() string`.', 'step_by_step': '1. Объявим `type OrderedStringer interface { cmp.Ordered; fmt.Stringer }`.\n2. Создадим `type Priority int` с методом `String() string`.\n3. Напишем `PrintSorted[T OrderedStringer](items []T)`.\n4. В `main` протестируем со срезом `[]Priority`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"cmp"\n\t"fmt"\n\t"slices"\n)\n\ntype OrderedStringer interface {\n\tcmp.Ordered\n\tfmt.Stringer\n}\n\ntype Priority int\n\nfunc (p Priority) String() string {\n\tswitch p {\n\tcase 1:\n\t\treturn "HIGH (1)"\n\tcase 2:\n\t\treturn "MEDIUM (2)"\n\tcase 3:\n\t\treturn "LOW (3)"\n\tdefault:\n\t\treturn fmt.Sprintf("UNKNOWN (%d)", p)\n\t}\n}\n\nfunc PrintSorted[T OrderedStringer](items []T) {\n\tsorted := slices.Clone(items)\n\tslices.SortFunc(sorted, func(a, b T) int {\n\t\treturn cmp.Compare(a, b)\n\t})\n\tfor _, item := range sorted {\n\t\tfmt.Printf("-> %s\\n", item.String())\n\t}\n}\n\nfunc main() {\n\ttasks := []Priority{3, 1, 2, 1, 3}\n\tPrintSorted(tasks)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# -> HIGH (1)\n# -> HIGH (1)\n# -> MEDIUM (2)\n# -> LOW (3)\n# -> LOW (3)'}], 'under_the_hood': 'Компилятор выполняет прямой статический вызов метода `item.String()` без поиска по таблице `itab`.', 'pitfalls': 'Базовый тип `int` не имеет метода `String()`, поэтому `PrintSorted([]int{1, 2})` вызовет ошибку компиляции.', 'bigtech_interview': '**Вопрос с собеседования:** «Вызываются ли методы в дженериках через динамическую таблицу интерфейсов (itab)?»\n**Ответ:** Нет, компилятор выполняет прямой статический вызов функции (direct call), что исключает накладные расходы на виртуальную диспетчеризацию.'}, {'num': 36, 'title': 'Извлечение ключей мапы: Keys[K comparable, V any]', 'task': 'Создай constraint `MapKey` как `comparable`. Напиши `Keys[K MapKey, V any](m map[K]V) []K`, извлекающий все ключи мапы в слайс.', 'theory': 'Извлечение всех ключей мапы — частая задача. Сигнатура `Keys[K comparable, V any](m map[K]V) []K` принимает мапу с любым сравнимым ключом и любым значением.', 'step_by_step': '1. Объявим `type MapKey comparable`.\n2. Напишем `Keys[K MapKey, V any](m map[K]V) []K`.\n3. Выделим память `make([]K, 0, len(m))`.\n4. В `main` извлечем ключи из `map[string]int` и `map[int]string`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype MapKey comparable\n\nfunc Keys[K MapKey, V any](m map[K]V) []K {\n\tkeys := make([]K, 0, len(m))\n\tfor k := range m {\n\t\tkeys = append(keys, k)\n\t}\n\treturn keys\n}\n\nfunc main() {\n\tuserAges := map[string]int{\n\t\t"Alice": 28,\n\t\t"Bob":   34,\n\t\t"Carol": 22,\n\t}\n\tfmt.Printf("Ключи userAges: %v\\n", Keys(userAges))\n\n\terrorCodes := map[int]string{\n\t\t400: "Bad Request",\n\t\t404: "Not Found",\n\t}\n\tfmt.Printf("Ключи errorCodes: %v\\n", Keys(errorCodes))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ключи userAges: [Alice Bob Carol]\n# Ключи errorCodes: [400 404]'}], 'under_the_hood': 'Итератор мапы начинает обход со случайного смещения в массиве бакетов `hmap`.', 'pitfalls': 'Порядок элементов в возвращенном слайсе не гарантирован и меняется между запусками программы.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему итерация по map в Go рандомизирована?»\n**Ответ:** Чтобы исключить зависимость логики приложения от внутреннего порядка бакетов хэш-таблицы.'}, {'num': 37, 'title': 'Дженерик-тип мапы: GenericMap[K, V]', 'task': 'Создай дженерик-мапу: `type GenericMap[K comparable, V any] map[K]V`. Напиши функцию `GetKeys[K comparable, V any](m GenericMap[K, V]) []K`, которая возвращает все ключи.', 'theory': 'Go позволяет объявлять именованные типы поверх мап с параметрами типов: `type GenericMap[K comparable, V any] map[K]V` и навешивать на них методы.', 'step_by_step': '1. Объявим `type GenericMap[K comparable, V any] map[K]V`.\n2. Реализуем метод `(m GenericMap[K, V]) Keys() []K`.\n3. В `main` протестируем работу метода.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype GenericMap[K comparable, V any] map[K]V\n\nfunc (m GenericMap[K, V]) Keys() []K {\n\tkeys := make([]K, 0, len(m))\n\tfor k := range m {\n\t\tkeys = append(keys, k)\n\t}\n\treturn keys\n}\n\nfunc main() {\n\tcache := GenericMap[string, int]{\n\t\t"cpu": 45,\n\t\t"ram": 78,\n\t}\n\tfmt.Println("Ключи cache:", cache.Keys())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ключи cache: [cpu ram]'}], 'under_the_hood': '`GenericMap` является ссылочным типом, передача ресивера копирует только 8-байтный указатель.', 'pitfalls': 'Методы на `GenericMap` не могут объявлять собственные независимые параметры типов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему методы не могут объявлять собственные параметры типов?»\n**Ответ:** Это сделало бы невозможным построение интерфейсных таблиц (itab) во время компиляции.'}, {'num': 38, 'title': 'Ограничение Numeric и умножение чисел', 'task': '**Кастомные интерфейсы-ограничения**: Объявите интерфейс-ограничение `Numeric`:\n```go\ntype Numeric interface {\n    ~int | ~int64 | ~float64\n}\n```\nНапишите функцию `Multiply[T Numeric](a, b T) T`. Объясните в комментариях роль знака тильды `~` (поддержка производных кастомных типов, например `type MyInt int`).', 'theory': '`Numeric` ограничивает допустимые типы тремя базовыми. Тильда `~` разрешает пользовательские типы вроде `type Price int64`.', 'step_by_step': '1. Объявим `type Numeric interface { ~int | ~int64 | ~float64 }`.\n2. Создадим `type Price int64`.\n3. Реализуем `Multiply[T Numeric](a, b T) T { return a * b }`.\n4. В `main` перемножим `Price`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Numeric interface {\n\t~int | ~int64 | ~float64\n}\n\ntype Price int64\n\nfunc Multiply[T Numeric](a, b T) T {\n\treturn a * b\n}\n\nfunc main() {\n\tvar unitPrice Price = 1500\n\tvar count Price = 3\n\ttotal := Multiply(unitPrice, count)\n\tfmt.Printf("Итоговая цена: %d (тип %T)\\n", total, total)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Итоговая цена: 4500 (тип main.Price)'}], 'under_the_hood': 'Компилятор подставляет инструкцию `IMUL` для целых чисел и `MULSD` для чисел с плавающей точкой.', 'pitfalls': 'Аргументы должны быть строго одинакового типа `(a, b T)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему типы Rubles и Dollars нельзя случайно перемножить в Multiply?»\n**Ответ:** Так как сигнатура требует одинаковый тип `T`, компилятор блокирует вызов `Multiply(rubles, dollars)` на этапе сборки.'}, {'num': 39, 'title': 'FindIndex и требование comparable для оператора ==', 'task': '**Ограничение `comparable`**: Напиши функцию `FindIndex[T comparable](slice []T, target T) int`, которая ищет элемент в срезе и возвращает его индекс (или -1). Пойми, почему тут нужен `comparable`, а не `any` (чтобы работал оператор `==`).', 'theory': 'Для операции `slice[i] == target` компилятор требует `T comparable`, так как для `any` оператор `==` запрещен.', 'step_by_step': '1. Реализуем `FindIndex[T comparable](slice []T, target T) int`.\n2. В цикле сравним элементы.\n3. В `main` найдем индекс элемента в `[]string`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc FindIndex[T comparable](slice []T, target T) int {\n\tfor i, v := range slice {\n\t\tif v == target {\n\t\t\treturn i\n\t\t}\n\t}\n\treturn -1\n}\n\nfunc main() {\n\tframeworks := []string{"Gin", "Echo", "Fiber"}\n\tfmt.Println("Индекс \'Fiber\':", FindIndex(frameworks, "Fiber"))\n\tfmt.Println("Индекс \'Chi\':", FindIndex(frameworks, "Chi"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# Индекс 'Fiber': 2\n# Индекс 'Chi': -1"}], 'under_the_hood': 'Для строк сравнивается сначала длина `len`, а затем вызывается `runtime.memequal`.', 'pitfalls': 'Поиск в срезе имеет сложность $O(N)$.', 'bigtech_interview': '**Вопрос с собеседования:** «Как оптимизировано сравнение строк в Go?»\n**Ответ:** Если `len` строк не равен, они не равны сразу ($O(1)$). Если указатели на массив байт равны, строки равны ($O(1)$).'}, {'num': 40, 'title': 'Универсальная свёртка Reduce для чисел и строк', 'task': 'Напишите функцию `Reduce[T, U any](s []T, initial U, f func(U, T) U) U` (свертка списка). Используйте её для подсчета суммы или конкатенации строк.', 'theory': '`Reduce` аккумулирует элементы среза в единый результат типа `U`.', 'step_by_step': '1. Объявим `Reduce[T, U any](s []T, initial U, f func(U, T) U) U`.\n2. В `main` подсчитаем суммарную длину всех строк.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Reduce[T, U any](s []T, initial U, f func(U, T) U) U {\n\tacc := initial\n\tfor _, v := range s {\n\t\tacc = f(acc, v)\n\t}\n\treturn acc\n}\n\nfunc main() {\n\twords := []string{"Go", "Generics", "Workout"}\n\ttotalLen := Reduce(words, 0, func(acc int, w string) int {\n\t\treturn acc + len(w)\n\t})\n\tfmt.Printf("Общая длина: %d символов\\n", totalLen)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Общая длина: 17 символов'}], 'under_the_hood': 'Типы `T` (`string`) и `U` (`int`) типизируются компилятором независимо без аллокаций в куче.', 'pitfalls': 'Передача тяжелых структур по значению может вызывать затраты на копирование.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы накладные расходы на вызов анонимной функции в цикле Reduce?»\n**Ответ:** Если замыкание не инлайнится, каждый косвенный вызов через указатель занимает несколько наносекунд.'}, {'num': 41, 'title': 'Constraint с Union типов и методами', 'task': 'Создай constraint с **union типов и методом**:\n```go\ntype StringOrInt interface {\n    ~string | ~int\n    String() string\n}\n```\nОбъясни, что метод должен быть доступен для **всех** типов в union (иначе ошибка компиляции при использовании).', 'theory': 'Когда constraint содержит union и методы, каждый конкретный тип обязан принадлежать к объединению И реализовывать указанный метод.', 'step_by_step': '1. Объявим `type StringOrInt interface { ~string | ~int; String() string }`.\n2. Создадим `type CustomString string` и `type CustomInt int` с методом `String() string`.\n3. В `main` вызовем `Describe` для обоих типов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"strconv"\n)\n\ntype StringOrInt interface {\n\t~string | ~int\n\tString() string\n}\n\ntype CustomString string\n\nfunc (cs CustomString) String() string {\n\treturn "CS:" + string(cs)\n}\n\ntype CustomInt int\n\nfunc (ci CustomInt) String() string {\n\treturn "CI:" + strconv.Itoa(int(ci))\n}\n\nfunc Describe[T StringOrInt](val T) string {\n\treturn val.String()\n}\n\nfunc main() {\n\tfmt.Println(Describe(CustomString("alpha")))\n\tfmt.Println(Describe(CustomInt(42)))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# CS:alpha\n# CI:42'}], 'under_the_hood': 'Компилятор статически проверяет принадлежность базового типа и наличие метода в наборе методов.', 'pitfalls': 'Встроенный примитивный `int` не имеет методов и вызовет ошибку `missing method String`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему нельзя объявить методы для встроенного типа int?»\n**Ответ:** Методы можно объявлять только для типов, определенных в текущем пакете (Package Locality Rule).'}, {'num': 42, 'title': 'Исправление constraint с помощью тильды ~', 'task': '**Символ тильды (`~`)**: Создай свой тип `type MyInt int`. Попробуй передать переменную этого типа в функцию `Sum` из упр. 240. Получишь ошибку. Исправь интерфейс `Number`, добавив `~` (`~int | ...`), чтобы разрешить использование любых типов, базовым для которых является `int`.', 'theory': 'Добавление тильды `~int` позволяет функции принимать производные типы `type MyInt int`.', 'step_by_step': '1. Объявим `type Number interface { ~int | ~float64 }`.\n2. Создадим `type MyInt int`.\n3. Реализуем `Sum2[T Number](a, b T) T`.\n4. В `main` сложим переменные `MyInt`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Number interface {\n\t~int | ~float64\n}\n\ntype MyInt int\n\nfunc Sum2[T Number](a, b T) T {\n\treturn a + b\n}\n\nfunc main() {\n\tvar a MyInt = 15\n\tvar b MyInt = 25\n\tfmt.Printf("Результат Sum2: %d (тип %T)\\n", Sum2(a, b), Sum2(a, b))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат Sum2: 40 (тип main.MyInt)'}], 'under_the_hood': 'Вызов мономорфизируется в функцию, возвращающую строгий тип `MyInt`.', 'pitfalls': '`~int` не совместим с `int64`, так как это разные базовые типы.', 'bigtech_interview': '**Вопрос с собеседования:** «Каков underlying type у type Alias = int и type NewType int?»\n**Ответ:** У `Alias` базовый тип буквально `int`. У `NewType` создается новый именованный тип с базовым типом `int`.'}, {'num': 43, 'title': 'Обобщенная пара Pair[T, U] с методами Swap и Equal', 'task': 'Реализуй `Pair[T, U any]` с полями `First T`, `Second U`. Методы: `Swap() Pair[U, T]`, `String() string`, `Equal(other Pair[T, U]) bool` (требует `T, U comparable` — добавь это ограничение на метод или сделай отдельный метод).', 'theory': '`Pair[T, U]` хранит пару разнотипных значений. Сравнение пар `EqualPairs` требует ограничения `comparable` на оба типа.', 'step_by_step': '1. Объявим `Pair[T, U any] struct { First T; Second U }`.\n2. Реализуем `Swap() Pair[U, T]` и `String() string`.\n3. Напишем `EqualPairs[T, U comparable](p1, p2 Pair[T, U]) bool`.\n4. В `main` протестируем пару.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Pair[T, U any] struct {\n\tFirst  T\n\tSecond U\n}\n\nfunc (p Pair[T, U]) Swap() Pair[U, T] {\n\treturn Pair[U, T]{First: p.Second, Second: p.First}\n}\n\nfunc (p Pair[T, U]) String() string {\n\treturn fmt.Sprintf("Pair(%v, %v)", p.First, p.Second)\n}\n\nfunc EqualPairs[T, U comparable](p1, p2 Pair[T, U]) bool {\n\treturn p1.First == p2.First && p1.Second == p2.Second\n}\n\nfunc main() {\n\tp1 := Pair[string, int]{First: "UserCount", Second: 42}\n\tfmt.Println("Оригинал:", p1)\n\tfmt.Println("Swap:    ", p1.Swap())\n\n\tp2 := Pair[string, int]{First: "UserCount", Second: 42}\n\tfmt.Println("p1 == p2:", EqualPairs(p1, p2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Оригинал: Pair(UserCount, 42)\n# Swap:     Pair(42, UserCount)\n# p1 == p2: true'}], 'under_the_hood': '`Pair[string, int]` и `Pair[int, string]` — разные типы с разной раскладкой полей.', 'pitfalls': 'Поскольку generic-методы на структурах запрещены, сравнение вынесено в отдельную функцию `EqualPairs`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему нельзя добавить метод Equal на структуру Pair[T, U any]?»\n**Ответ:** Потому что `any` не гарантирует наличие оператора `==`. Для метода `Equal` ограничение `comparable` должно быть наложено на саму структуру.'}, {'num': 44, 'title': 'Ограничение для строк и байтовых слайсов BytesOrString', 'task': 'Создай constraint для byte-слайсов и строк:\n```go\ntype BytesOrString interface {\n    ~[]byte | ~string\n}\n```\nНапиши `Len[T BytesOrString](v T) int`, возвращающий `len(v)`. Покажи, что `len` работает для обоих типов без приведения.', 'theory': '`len()` работает и со строками, и со слайсами байт. `BytesOrString` объединяет `~[]byte | ~string`.', 'step_by_step': '1. Объявим `type BytesOrString interface { ~[]byte | ~string }`.\n2. Напишем `Len[T BytesOrString](v T) int { return len(v) }`.\n3. В `main` вызовем для `string` и `[]byte`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype BytesOrString interface {\n\t~[]byte | ~string\n}\n\nfunc Len[T BytesOrString](v T) int {\n\treturn len(v)\n}\n\nfunc main() {\n\ts := "Gopher"\n\tb := []byte{\'G\', \'o\', \'p\', \'h\', \'e\', \'r\'}\n\tfmt.Println("Len string:", Len(s))\n\tfmt.Println("Len []byte:", Len(b))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Len string: 6\n# Len []byte: 6'}], 'under_the_hood': '`len` читает поле длины из `StringHeader` или `SliceHeader` напрямую.', 'pitfalls': 'Функция `cap()` запрещена для `BytesOrString`, так как у строк нет емкости.', 'bigtech_interview': '**Вопрос с собеседования:** «Какие встроенные функции разрешены в Union Types?»\n**Ответ:** Только те, которые определены для всех типов в объединении.'}, {'num': 45, 'title': 'Анализ ошибок несоответствия ограничений компилятора', 'task': 'Попробуйте передать в дженерик-функцию структуру, которая не удовлетворяет constraint (например, слайс в `Contains`). Изучите понятную ошибку компилятора.', 'theory': 'При нарушении ограничений компилятор Go генерирует подробные сообщения об ошибках с указанием точной причины (несравнимость, отсутствие метода).', 'step_by_step': '1. Объявим `Contains[T comparable](s []T, v T) bool`.\n2. В `main` покажем успешный вызов с `[]int`.\n3. В комментариях зафиксируем ошибку для среза срезов `[][]int`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Contains[T comparable](s []T, v T) bool {\n\tfor _, item := range s {\n\t\tif item == v {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc main() {\n\tfmt.Println("Contains int:", Contains([]int{1, 2, 3}, 2))\n\n\t// matrix := [][]int{{1, 2}, {3, 4}}\n\t// Contains(matrix, []int{1, 2})\n\t// Ошибка: []int does not satisfy comparable\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Contains int: true'}], 'under_the_hood': 'Проверка ограничений происходит на этапе статического анализа дерева типов `types2`.', 'pitfalls': 'Для несравнимых типов используйте предикат `ContainsFunc`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как найти элемент в слайсе несравнимых структур?»\n**Ответ:** Использовать предикат `ContainsFunc[T any](s []T, eq func(T) bool)`.'}, {'num': 46, 'title': 'Обобщённый односвязный список List[T any]', 'task': 'Обобщённый односвязный список `List[T any]` с методами `Insert`, `Find`, `Delete`.', 'theory': 'Односвязный список состоит из узлов `Node[T]` с полями `Value T` и `Next *Node[T]`.', 'step_by_step': '1. Объявим `Node[T any]` и `List[T any]`.\n2. Реализуем `Insert(v T)`, `Find(pred func(T) bool) *Node[T]`, `Len() int`.\n3. В `main` протестируем список строк.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Node[T any] struct {\n\tValue T\n\tNext  *Node[T]\n}\n\ntype List[T any] struct {\n\thead   *Node[T]\n\tlength int\n}\n\nfunc (l *List[T]) Insert(val T) {\n\tnewNode := &Node[T]{Value: val, Next: l.head}\n\tl.head = newNode\n\tl.length++\n}\n\nfunc (l *List[T]) Find(predicate func(T) bool) *Node[T] {\n\tcurr := l.head\n\tfor curr != nil {\n\t\tif predicate(curr.Value) {\n\t\t\treturn curr\n\t\t}\n\t\tcurr = curr.Next\n\t}\n\treturn nil\n}\n\nfunc (l *List[T]) Len() int {\n\treturn l.length\n}\n\nfunc main() {\n\tlist := &List[string]{}\n\tlist.Insert("Redis")\n\tlist.Insert("PostgreSQL")\n\tlist.Insert("ClickHouse")\n\n\tfound := list.Find(func(s string) bool { return s == "PostgreSQL" })\n\tif found != nil {\n\t\tfmt.Println("Найден узел:", found.Value)\n\t}\n\tfmt.Println("Длина списка:", list.Len())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Найден узел: PostgreSQL\n# Длина списка: 3'}], 'under_the_hood': 'Каждый узел `Node[T]` аллоцируется в куче и связывается через указатель `Next`.', 'pitfalls': 'Связные списки проигрывают слайсам по производительности из-за Cache Misses.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему слайсы в Go быстрее связных списков?»\n**Ответ:** Слайс расположен в непрерывной памяти, что позволяет процессору предварительно загружать данные в кэш (L1/L2 prefetching).'}, {'num': 47, 'title': 'Эксперимент без тильды: SpecialInt и Numeric', 'task': '**Эксперимент без тильды `~`**: Уберите знак тильды `~` из ограничения `Numeric` в предыдущей задаче. Создайте кастомный тип `type SpecialInt int` и попробуйте передать переменную этого типа в функцию `Multiply`. Зафиксируйте ошибку компиляции. Верните тильду на место и проверьте результат.', 'theory': 'Без тильды `~` компилятор проверяет точное имя типа, отвергая пользовательские типы с тем же базовым представлением.', 'step_by_step': '1. Объявим `type ApproxNumeric interface { ~int | ~float64 }`.\n2. Создадим `type SpecialInt int`.\n3. Реализуем `MultiplyApprox[T ApproxNumeric](a, b T) T`.\n4. В `main` вызовем с `SpecialInt`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype SpecialInt int\n\ntype ApproxNumeric interface {\n\t~int | ~float64\n}\n\nfunc MultiplyApprox[T ApproxNumeric](a, b T) T {\n\treturn a * b\n}\n\nfunc main() {\n\tvar x SpecialInt = 10\n\tvar y SpecialInt = 5\n\n\tres := MultiplyApprox(x, y)\n\tfmt.Printf("Multiply SpecialInt: %d (тип %T)\\n", res, res)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Multiply SpecialInt: 50 (тип main.SpecialInt)'}], 'under_the_hood': 'Тильда заставляет компилятор обращаться к `T.Underlying()` вместо проверки точного `types.Named`.', 'pitfalls': 'Всегда используйте тильду в библиотечных ограничениях общего назначения.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в пакете cmp все типы имеют тильду?»\n**Ответ:** Чтобы пользовательские типы могли сортироваться и сравниваться стандартными функциями без приведений.'}, {'num': 48, 'title': 'Вывод типов (Type Inference): явное vs неявное инстанцирование', 'task': '**Вывод типов (Type Inference)**: Вызови функцию `Sum` из упр. 240 двумя способами: с явным указанием типа `Sum[float64](1.5, 2.5)` и без него `Sum(1.5, 2.5)` — позволь компилятору самому догадаться.', 'theory': 'Type Inference выводит параметры типов из типов аргументов вызова функции во время компиляции.', 'step_by_step': '1. Объявим `Sum[T ~float64 | ~int](a, b T) T { return a + b }`.\n2. Вызовем с явным `[float64]` и с неявным выводом.\n3. Сравним в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Sum[T ~float64 | ~int](a, b T) T {\n\treturn a + b\n}\n\nfunc main() {\n\tres1 := Sum[float64](1.5, 2.5)\n\tfmt.Printf("Явный вызов: %.2f (%T)\\n", res1, res1)\n\n\tres2 := Sum(1.5, 2.5)\n\tfmt.Printf("Авто вывод:  %.2f (%T)\\n", res2, res2)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Явный вызов: 4.00 (float64)\n# Авто вывод:  4.00 (float64)'}], 'under_the_hood': 'Оба варианта компилируются в идентичный машинный код.', 'pitfalls': 'Если аргументы имеют разные типы (`Sum(1, 2.5)`), автовывод вызовет ошибку `mismatched types`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда явное инстанцирование [T] строго обязательно?»\n**Ответ:** Когда параметр типа `T` используется только как возвращаемое значение (например `func New[T any]() *T`).'}, {'num': 49, 'title': 'Хелпер для создания указателей: Ptr[T any]', 'task': 'Напишите параметризованную функцию `Ptr[T any](val T) *T`, которая возвращает указатель на переданное значение. Это очень удобный хелпер для тестов и заполнения структур.', 'theory': 'В Go нельзя взять адрес от литерала напрямую (`&42` — ошибка). Функция `Ptr[T any](val T) *T` создает указатель на значение любого типа.', 'step_by_step': '1. Объявим `func Ptr[T any](val T) *T { return &val }`.\n2. Создадим структуру `UserConfig` с указателями.\n3. В `main` заполним поля через `Ptr`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Ptr[T any](val T) *T {\n\treturn &val\n}\n\ntype UserConfig struct {\n\tHost    *string\n\tPort    *int\n\tDebug   *bool\n\tTimeout *float64\n}\n\nfunc main() {\n\tcfg := UserConfig{\n\t\tHost:    Ptr("localhost"),\n\t\tPort:    Ptr(8080),\n\t\tDebug:   Ptr(true),\n\t\tTimeout: Ptr(5.5),\n\t}\n\n\tfmt.Printf("Host: %s, Port: %d, Debug: %v, Timeout: %.1f\\n",\n\t\t*cfg.Host, *cfg.Port, *cfg.Debug, *cfg.Timeout)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Host: localhost, Port: 8080, Debug: true, Timeout: 5.5'}], 'under_the_hood': 'Escape Analysis компилятора аллоцирует значение в куче или инлайнит создание объекта.', 'pitfalls': 'Не используйте указатели на примитивы без необходимости.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go нельзя взять адрес &100?»\n**Ответ:** Литералы являются неадресуемыми значениями (unaddressable) и не имеют постоянного адреса в памяти.'}, {'num': 50, 'title': 'Constraint со строгим упорядочиванием и кастомным методом', 'task': 'Создай constraint, требующий и `constraints.Ordered`, и кастомный метод:\n```go\ntype NamedOrdered interface {\n    cmp.Ordered\n    Name() string\n}\n```\nПокажи, что тип должен удовлетворять **обоим** требованиям.', 'theory': '`NamedOrdered` демонстрирует строгое пересечение: значение можно сравнивать оператором `<` и у него есть метод `Name()`.', 'step_by_step': '1. Объявим `NamedOrdered interface { cmp.Ordered; Name() string }`.\n2. Создадим `type Version int` с методом `Name() string`.\n3. Напишем `MaxNamed[T NamedOrdered](a, b T) T`.\n4. В `main` вызовем `MaxNamed`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"cmp"\n\t"fmt"\n)\n\ntype NamedOrdered interface {\n\tcmp.Ordered\n\tName() string\n}\n\ntype Version int\n\nfunc (v Version) Name() string {\n\treturn fmt.Sprintf("v%d.0.0", v)\n}\n\nfunc MaxNamed[T NamedOrdered](a, b T) T {\n\tif a > b {\n\t\treturn a\n\t}\n\treturn b\n}\n\nfunc main() {\n\tv1 := Version(1)\n\tv2 := Version(2)\n\n\tmaxV := MaxNamed(v1, v2)\n\tfmt.Printf("Максимальная версия: %s (значение: %d)\\n", maxV.Name(), maxV)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Максимальная версия: v2.0.0 (значение: 2)'}], 'under_the_hood': 'Компилятор статически проверяет наличие оператора `>` и метода `Name()`.', 'pitfalls': 'Обычный `int` вызовет ошибку `missing method Name`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как называется комбинация Type Sets и Method Sets?»\n**Ответ:** Обобщенные интерфейсы (General Interfaces).'}, {'num': 51, 'title': 'Сравнение возможностей: any против comparable', 'task': 'Покажи разницу между `any` и `comparable` на примере: `SearchAny[T any](slice []T, item T)` не может использовать `==`, а `SearchComparable[T comparable]` может. Объясни, когда что использовать.', 'theory': '`any` разрешает несравнимые типы (слайсы, функции), поэтому `==` запрещен. `comparable` гарантирует поддержку `==`.', 'step_by_step': '1. Напишем `SearchComparable` и `SearchAny` с компаратором.\n2. В `main` продемонстрируем оба вызова.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"slices"\n)\n\nfunc SearchComparable[T comparable](slice []T, item T) bool {\n\tfor _, v := range slice {\n\t\tif v == item {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc SearchAny[T any](slice []T, item T, eq func(T, T) bool) bool {\n\tfor _, v := range slice {\n\t\tif eq(v, item) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc main() {\n\tnums := []int{10, 20, 30}\n\tfmt.Println("SearchComparable:", SearchComparable(nums, 20))\n\n\tmatrix := [][]int{{1, 2}, {3, 4}}\n\tfound := SearchAny(matrix, []int{3, 4}, func(a, b []int) bool {\n\t\treturn slices.Equal(a, b)\n\t})\n\tfmt.Println("SearchAny:", found)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# SearchComparable: true\n# SearchAny: true'}], 'under_the_hood': '`SearchComparable` мономорфизируется в машинные опкоды, а `SearchAny` делает косвенный вызов функции-предиката.', 'pitfalls': 'Для простых типов всегда используйте `comparable`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в standard library есть и slices.Contains, и slices.ContainsFunc?»\n**Ответ:** `Contains` дает максимальную скорость для простых типов через `==`, а `ContainsFunc` дает гибкость для сложных объектов.'}, {'num': 52, 'title': 'Рефлексия внутри дженериков: PrintAny[T any]', 'task': 'Напишите функцию `PrintAny[T any](val T)`, которая принимает любой тип и использует `reflect` для вывода информации о нём. Сравните это с использованием пустого интерфейса `any`.', 'theory': 'Пакет `reflect` позволяет динамически анализировать тип `T` во время выполнения.', 'step_by_step': '1. Реализуем `PrintAny[T any](val T)` с `reflect.TypeOf` и `unsafe.Sizeof`.\n2. В `main` вызовем для `int`, `string` и структуры.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"reflect"\n\t"unsafe"\n)\n\nfunc PrintAny[T any](val T) {\n\tt := reflect.TypeOf(val)\n\tfmt.Printf("Тип: %-15s | Kind: %-10s | Размер: %d байт | Значение: %v\\n",\n\t\tt.String(), t.Kind(), unsafe.Sizeof(val), val)\n}\n\ntype ServerState struct {\n\tActive bool\n\tPort   int\n}\n\nfunc main() {\n\tPrintAny(42)\n\tPrintAny("Generics in Go")\n\tPrintAny(ServerState{Active: true, Port: 8080})\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Тип: int             | Kind: int        | Размер: 8 байт | Значение: 42\n# Тип: string          | Kind: string     | Размер: 16 байт | Значение: Generics in Go\n# Тип: main.ServerState | Kind: struct     | Размер: 16 байт | Значение: {true 8080}'}], 'under_the_hood': '`unsafe.Sizeof(val)` вычисляется во время компиляции.', 'pitfalls': 'Рефлексия в критических циклах приводит к замедлению программы.', 'bigtech_interview': '**Вопрос с собеседования:** «Замедляет ли reflect работу generic-функций?»\n**Ответ:** Да, динамический анализ метаданных в рантайме значительно медленнее статических вызовов.'}, {'num': 53, 'title': 'Обобщенный декоратор функций: WrapWithLogging[T any]', 'task': 'Обобщённый метод структуры: `Service.WrapWithLogging[T any](fn func() T) func() T`, логирующая до и после вызова.', 'theory': 'Generic-декоратор оборачивает функцию логированием, сохраняя строгий тип возвращаемого значения.', 'step_by_step': '1. Объявим `WrapWithLogging[T any](name string, fn func() T) func() T`.\n2. Замерим время выполнения `time.Since(start)`.\n3. В `main` обернем функции.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc WrapWithLogging[T any](name string, fn func() T) func() T {\n\treturn func() T {\n\t\tfmt.Printf("[%s] Старт...\\n", name)\n\t\tstart := time.Now()\n\t\tresult := fn()\n\t\tfmt.Printf("[%s] Финиш за %v. Результат: %v\\n", name, time.Since(start), result)\n\t\treturn result\n\t}\n}\n\nfunc main() {\n\tcompute := func() int { return 100 + 200 }\n\tlogged := WrapWithLogging("Compute", compute)\n\tres := logged()\n\tfmt.Println("Итог:", res)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Compute] Старт...\n# [Compute] Финиш за ... Результат: 300\n# Итог: 300'}], 'under_the_hood': 'Замыкание генерирует специализированный входной фрейм под тип `T`.', 'pitfalls': 'Для функций с ошибками используйте пару `(T, error)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать generic Retry с backoff?»\n**Ответ:** Написать `Retry[T any](attempts int, fn func() (T, error)) (T, error)` с циклом повторов.'}, {'num': 54, 'title': 'Underlying Type: концепция базового типа в Go', 'task': 'Создай `type MyFloat float64`. Покажи, что constraint с `~float64` принимает `MyFloat`, а без `~` — только строго `float64`. Объясни **underlying type** concept.', 'theory': '`type MyFloat float64` имеет базовый тип `float64`. Тильда `~float64` разрешает любые производные типы.', 'step_by_step': '1. Объявим `type MyFloat float64`.\n2. Напишем `Abs[T ~float64](v T) T`.\n3. В `main` протестируем с `float64` и `MyFloat`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype MyFloat float64\n\nfunc Abs[T ~float64](v T) T {\n\tif v < 0 {\n\t\treturn -v\n\t}\n\treturn v\n}\n\nfunc main() {\n\tvar f float64 = -3.14\n\tvar mf MyFloat = -99.9\n\n\tfmt.Printf("Abs(float64): %.2f (%T)\\n", Abs(f), Abs(f))\n\tfmt.Printf("Abs(MyFloat): %.2f (%T)\\n", Abs(mf), Abs(mf))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Abs(float64): 3.14 (float64)\n# Abs(MyFloat): 99.90 (main.MyFloat)'}], 'under_the_hood': 'Оператор унарного минуса `-v` разрешен, так как он поддерживается базовым типом `float64`.', 'pitfalls': '`~float64` не принимает `float32`, так как это разные базовые типы.', 'bigtech_interview': '**Вопрос с собеседования:** «Каков underlying type у цепочки type A int; type B A; type C B?»\n**Ответ:** Underlying type для всех трех типов — примитивный `int`.'}, {'num': 55, 'title': 'Constraint с интерфейсом Closer и функция CloseAll', 'task': 'Создай constraint с интерфейсом, имеющим метод: `type Closer interface { Close() error }`. Напиши `CloseAll[T Closer](items []T) []error`, закрывающий всё и собирающий ошибки.', 'theory': '`CloseAll[T Closer](items []T)` принимает срез любых объектов с методом `Close() error` без промежуточных аллокаций `[]io.Closer`.', 'step_by_step': '1. Объявим `type Closer interface { Close() error }`.\n2. Создадим структуры `FakeFile` и `FakeSocket`.\n3. Реализуем `CloseAll[T Closer](items []T) []error`.\n4. В `main` закроем файлы и сокеты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Closer interface {\n\tClose() error\n}\n\ntype FakeFile struct {\n\tName string\n}\n\nfunc (f *FakeFile) Close() error {\n\tfmt.Printf("Файл %s закрыт\\n", f.Name)\n\treturn nil\n}\n\ntype FakeSocket struct {\n\tPort int\n}\n\nfunc (s *FakeSocket) Close() error {\n\tfmt.Printf("Сокет %d закрыт\\n", s.Port)\n\treturn nil\n}\n\nfunc CloseAll[T Closer](items []T) []error {\n\tvar errs []error\n\tfor _, item := range items {\n\t\tif err := item.Close(); err != nil {\n\t\t\terrs = append(errs, err)\n\t\t}\n\t}\n\treturn errs\n}\n\nfunc main() {\n\tfiles := []*FakeFile{{Name: "app.log"}, {Name: "data.db"}}\n\tCloseAll(files)\n\n\tsockets := []*FakeSocket{{Port: 8080}}\n\tCloseAll(sockets)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Файл app.log закрыт\n# Файл data.db закрыт\n# Сокет 8080 закрыт'}], 'under_the_hood': 'Дженерик принимает срез указателей `[]*FakeFile` напрямую без создания промежуточного слайса интерфейсов.', 'pitfalls': 'Если метод объявлен на указателе `*FakeFile`, передавайте срез указателей `[]*FakeFile`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем плюс CloseAll[T Closer]([]T) перед CloseAll([]Closer)?»\n**Ответ:** В Go срез `[]*FakeFile` нельзя передать в `[]Closer` без полного копирования. Дженерик решает это с 0 аллокаций.'}, {'num': 56, 'title': 'Поиск максимума по критерию: MaxBy[T, U]', 'task': 'Реализуйте функцию `MaxBy[T any, U cmp.Ordered](s []T, f func(T) U) T`, которая находит элемент в слайсе, имеющий максимальное значение по заданному критерию (например, найти `User` с максимальным `Age`).', 'theory': '`MaxBy` находит элемент за один проход ($O(N)$), извлекая ключ сортировки через функцию `f(item)`.', 'step_by_step': '1. Объявим `MaxBy[T any, U cmp.Ordered](s []T, f func(T) U) T`.\n2. В цикле сравним ключи `f(v) > maxKey`.\n3. В `main` найдем пользователя с наибольшим возрастом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"cmp"\n\t"fmt"\n)\n\ntype User struct {\n\tName string\n\tAge  int\n}\n\nfunc MaxBy[T any, U cmp.Ordered](s []T, f func(T) U) T {\n\tif len(s) == 0 {\n\t\tvar zero T\n\t\treturn zero\n\t}\n\tbest := s[0]\n\tmaxKey := f(s[0])\n\tfor _, v := range s[1:] {\n\t\tkey := f(v)\n\t\tif key > maxKey {\n\t\t\tmaxKey = key\n\t\t\tbest = v\n\t\t}\n\t}\n\treturn best\n}\n\nfunc main() {\n\tusers := []User{\n\t\t{Name: "Иван", Age: 25},\n\t\t{Name: "Елена", Age: 34},\n\t\t{Name: "Дмитрий", Age: 29},\n\t}\n\toldest := MaxBy(users, func(u User) int { return u.Age })\n\tfmt.Printf("Самый старший: %s (%d лет)\\n", oldest.Name, oldest.Age)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Самый старший: Елена (34 лет)'}], 'under_the_hood': 'Сравнение мономорфизируется под тип `int` без аллокаций в куче.', 'pitfalls': 'Сохраняйте значение `key := f(v)` в локальную переменную, чтобы не вычислять его дважды.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать MinBy и MaxBy через единую функцию?»\n**Ответ:** Передать функцию-компаратор `less func(a, b T) bool`.'}, {'num': 57, 'title': 'Полнофункциональный Stack[T] с Peek и IsEmpty', 'task': 'Реализуй `Stack[T any]` на слайсе с методами `Push(v T)`, `Pop() (T, bool)`, `Peek() (T, bool)`, `IsEmpty() bool`.', 'theory': '`Peek` просматривает верхний элемент без извлечения. Сигнатура `(T, bool)` сигнализирует об успехе.', 'step_by_step': '1. Объявим `Stack[T any] struct { items []T }`.\n2. Реализуем `Push`, `Pop`, `Peek`, `IsEmpty`.\n3. Проверим в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Stack[T any] struct {\n\titems []T\n}\n\nfunc (s *Stack[T]) Push(v T) {\n\ts.items = append(s.items, v)\n}\n\nfunc (s *Stack[T]) Pop() (T, bool) {\n\tif len(s.items) == 0 {\n\t\tvar zero T\n\t\treturn zero, false\n\t}\n\tlastIdx := len(s.items) - 1\n\tval := s.items[lastIdx]\n\ts.items = s.items[:lastIdx]\n\treturn val, true\n}\n\nfunc (s *Stack[T]) Peek() (T, bool) {\n\tif len(s.items) == 0 {\n\t\tvar zero T\n\t\treturn zero, false\n\t}\n\treturn s.items[len(s.items)-1], true\n}\n\nfunc (s *Stack[T]) IsEmpty() bool {\n\treturn len(s.items) == 0\n}\n\nfunc main() {\n\ts := &Stack[string]{}\n\ts.Push("first")\n\ts.Push("second")\n\n\ttop, _ := s.Peek()\n\tfmt.Println("Peek top:", top)\n\n\tfor !s.IsEmpty() {\n\t\tv, _ := s.Pop()\n\t\tfmt.Println("Pop:", v)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Peek top: second\n# Pop: second\n# Pop: first'}], 'under_the_hood': '`Peek` возвращает значение по индексу без аллокаций памяти.', 'pitfalls': 'Для потокобезопасности используйте `sync.Mutex`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова амортизированная сложность Push в стек на слайсе?»\n**Ответ:** $O(1)$ амортизированная, так как базовый массив удваивается при заполнении.'}, {'num': 58, 'title': 'Проверка на нулевое значение: IsZero[T comparable]', 'task': '`IsZero[T comparable](v T) bool` — проверка на нулевое значение (сравнение с `*new(T)`).', 'theory': 'Сравнение `var zero T; return v == zero` проверяет, равно ли значение своему дефолтному состоянию.', 'step_by_step': '1. Объявим `IsZero[T comparable](v T) bool`.\n2. В `main` проверим числа, строки и структуры.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc IsZero[T comparable](v T) bool {\n\tvar zero T\n\treturn v == zero\n}\n\ntype Point struct {\n\tX, Y int\n}\n\nfunc main() {\n\tfmt.Println("IsZero(0):", IsZero(0))\n\tfmt.Println("IsZero(42):", IsZero(42))\n\tfmt.Println("IsZero(\\"\\"):", IsZero(""))\n\tfmt.Println("IsZero(Point{0, 0}):", IsZero(Point{0, 0}))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# IsZero(0): true\n# IsZero(42): false\n# IsZero(""): true\n# IsZero(Point{0, 0}): true'}], 'under_the_hood': 'Компилятор выполняет прямое побитовое сравнение со статической zero-памятью.', 'pitfalls': 'Слайсы не поддерживают `==`, для них проверяйте `len(s) == 0`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие IsZero от reflect.ValueOf(v).IsZero()?»\n**Ответ:** Дженерик выполняется статически за $O(1)$ без аллокаций, а рефлексия выполняет динамический анализ в рантайме.'}, {'num': 59, 'title': 'Метод IsEmpty для обобщенной структуры Stack[T]', 'task': 'Напиши метод для дженерик-структуры: добавь метод `IsEmpty()` для `Stack[T]`.', 'theory': 'Методы структур объявляются с параметром типа в ресивере `(s *Stack[T])`.', 'step_by_step': '1. Объявим `Stack[T any]`.\n2. Реализуем `(s *Stack[T]) IsEmpty() bool`.\n3. Проверим в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Stack[T any] struct {\n\titems []T\n}\n\nfunc (s *Stack[T]) Push(v T) {\n\ts.items = append(s.items, v)\n}\n\nfunc (s *Stack[T]) IsEmpty() bool {\n\treturn len(s.items) == 0\n}\n\nfunc main() {\n\ts := &Stack[int]{}\n\tfmt.Println("Пуст:", s.IsEmpty())\n\ts.Push(10)\n\tfmt.Println("Пуст после Push:", s.IsEmpty())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Пуст: true\n# Пуст после Push: false'}], 'under_the_hood': 'Параметр `T` передается в скрытый дескриптор метода структуры.', 'pitfalls': 'Обязательно указывайте `[T]` в ресивере: `(s *Stack[T])`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в ресивере метода обязательно указывать [T]?»\n**Ответ:** Потому что `Stack` без параметров — это обобщенный шаблон типа, а `Stack[T]` — конкретный инстанцированный тип.'}, {'num': 60, 'title': 'Обобщенная FIFO очередь: Queue[T any]', 'task': 'Реализуй `Queue[T any]` на слайсе (или через кольцевой буфер) с методами `Enqueue(v T)`, `Dequeue() (T, bool)`, `Len() int`.', 'theory': 'Очередь работает по принципу FIFO. Зануление первого элемента перед срезкой защищает от утечек памяти.', 'step_by_step': '1. Объявим `type Queue[T any] struct { items []T }`.\n2. Реализуем `Enqueue` и `Dequeue`.\n3. В `main` проверим обработку элементов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Queue[T any] struct {\n\titems []T\n}\n\nfunc (q *Queue[T]) Enqueue(v T) {\n\tq.items = append(q.items, v)\n}\n\nfunc (q *Queue[T]) Dequeue() (T, bool) {\n\tif len(q.items) == 0 {\n\t\tvar zero T\n\t\treturn zero, false\n\t}\n\tval := q.items[0]\n\tvar zero T\n\tq.items[0] = zero\n\tq.items = q.items[1:]\n\treturn val, true\n}\n\nfunc (q *Queue[T]) Len() int {\n\treturn len(q.items)\n}\n\nfunc main() {\n\tq := &Queue[string]{}\n\tq.Enqueue("Msg 1")\n\tq.Enqueue("Msg 2")\n\n\tfor q.Len() > 0 {\n\t\tmsg, _ := q.Dequeue()\n\t\tfmt.Println("Обработано:", msg)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обработано: Msg 1\n# Обработано: Msg 2'}], 'under_the_hood': 'Зануление `q.items[0] = zero` позволяет GC освободить объект из памяти.', 'pitfalls': 'Постоянная срезка `q.items[1:]` оставляет неиспользуемое начало базового массива. Для тяжелых очередей применяйте кольцевой буфер.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать очередь с $O(1)$ Dequeue без утечек памяти?»\n**Ответ:** Использовать Ring Buffer фиксированного размера или очередь на двух стеках (`in` и `out`).'}, {'num': 61, 'title': 'Обобщенный кэш Cache[K, V] на мапе', 'task': '**Обобщенная Мапа (Кэш)**: Реализуй простую структуру `Cache[K comparable, V any]` с мапой внутри и методами `Set(k K, v V)` и `Get(k K) (V, bool)`.', 'theory': '`Cache[K, V]` оборачивает мапу, гарантируя типобезопасный доступ по ключу.', 'step_by_step': '1. Объявим `type Cache[K comparable, V any] struct { store map[K]V }`.\n2. Реализуем `Set` и `Get`.\n3. В `main` сохраним сессию пользователя.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Cache[K comparable, V any] struct {\n\tstore map[K]V\n}\n\nfunc NewCache[K comparable, V any]() *Cache[K, V] {\n\treturn &Cache[K, V]{store: make(map[K]V)}\n}\n\nfunc (c *Cache[K, V]) Set(k K, v V) {\n\tc.store[k] = v\n}\n\nfunc (c *Cache[K, V]) Get(k K) (V, bool) {\n\tval, ok := c.store[k]\n\treturn val, ok\n}\n\ntype Session struct {\n\tUserID string\n\tRole   string\n}\n\nfunc main() {\n\tsessCache := NewCache[string, Session]()\n\tsessCache.Set("token_abc", Session{UserID: "u123", Role: "admin"})\n\n\tif sess, ok := sessCache.Get("token_abc"); ok {\n\t\tfmt.Printf("Сессия: UserID=%s, Role=%s\\n", sess.UserID, sess.Role)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сессия: UserID=u123, Role=admin'}], 'under_the_hood': '`Get` и `Set` работают напрямую со структурой `hmap` без аллокаций ключей.', 'pitfalls': 'Мапа не является потокобезопасной. При параллельном доступе нужен `sync.RWMutex`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему map в Go не сделали потокобезопасной по умолчанию?»\n**Ответ:** Блокировки замедлили бы 95% кода, который выполняется в рамках одной горутины.'}, {'num': 62, 'title': 'Множество Set[T comparable]: Union, Intersection, ToSlice', 'task': 'Реализуй `Set[T comparable]` на мапе с методами `Add(v T)`, `Remove(v T)`, `Contains(v T) bool`, `Union(other Set[T]) Set[T]`, `Intersection(other Set[T]) Set[T]`, `Len() int`, `ToSlice() []T`.', 'theory': 'Множество на `map[T]struct{}` обеспечивает математические операции объединения и пересечения.', 'step_by_step': '1. Реализуем `Set[T comparable]`.\n2. Реализуем `Union` и `Intersection`.\n3. В `main` проверим операции над множествами.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Set[T comparable] struct {\n\tdata map[T]struct{}\n}\n\nfunc NewSet[T comparable](items ...T) *Set[T] {\n\ts := &Set[T]{data: make(map[T]struct{})}\n\tfor _, item := range items {\n\t\ts.Add(item)\n\t}\n\treturn s\n}\n\nfunc (s *Set[T]) Add(v T)           { s.data[v] = struct{}{} }\nfunc (s *Set[T]) Contains(v T) bool { _, ok := s.data[v]; return ok }\n\nfunc (s *Set[T]) Union(other *Set[T]) *Set[T] {\n\tres := NewSet[T]()\n\tfor k := range s.data {\n\t\tres.Add(k)\n\t}\n\tfor k := range other.data {\n\t\tres.Add(k)\n\t}\n\treturn res\n}\n\nfunc (s *Set[T]) Intersection(other *Set[T]) *Set[T] {\n\tres := NewSet[T]()\n\tfor k := range s.data {\n\t\tif other.Contains(k) {\n\t\t\tres.Add(k)\n\t\t}\n\t}\n\treturn res\n}\n\nfunc (s *Set[T]) ToSlice() []T {\n\tres := make([]T, 0, len(s.data))\n\tfor k := range s.data {\n\t\tres = append(res, k)\n\t}\n\treturn res\n}\n\nfunc main() {\n\ts1 := NewSet(1, 2, 3)\n\ts2 := NewSet(2, 3, 4)\n\n\tfmt.Println("Union:       ", s1.Union(s2).ToSlice())\n\tfmt.Println("Intersection:", s1.Intersection(s2).ToSlice())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Union:        [1 2 3 4]\n# Intersection: [2 3]'}], 'under_the_hood': '`struct{}` занимает 0 байт памяти в значениях мапы.', 'pitfalls': 'Порядок в `ToSlice()` случайный из-за рандомизации мапы.', 'bigtech_interview': '**Вопрос с собеседования:** «Как оптимизировать Intersection двух больших множеств?»\n**Ответ:** Итерироваться по меньшему множеству, проверяя наличие в большем.'}, {'num': 63, 'title': 'Связный список LinkedList[T] с Add и PrintAll', 'task': 'Реализуйте параметризованный связный список `LinkedList[T any]` с методами `Add(T)` и `PrintAll()`.', 'theory': 'Связный список хранит элементы последовательно через указатели `Next`.', 'step_by_step': '1. Объявим `LinkedList[T any] struct { head, tail *Node[T] }`.\n2. Реализуем `Add` и `PrintAll`.\n3. В `main` проверим вывод.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Node[T any] struct {\n\tVal  T\n\tNext *Node[T]\n}\n\ntype LinkedList[T any] struct {\n\thead, tail *Node[T]\n}\n\nfunc (l *LinkedList[T]) Add(v T) {\n\tnewNode := &Node[T]{Val: v}\n\tif l.head == nil {\n\t\tl.head = newNode\n\t\tl.tail = newNode\n\t\treturn\n\t}\n\tl.tail.Next = newNode\n\tl.tail = newNode\n}\n\nfunc (l *LinkedList[T]) PrintAll() {\n\tcurr := l.head\n\tfor curr != nil {\n\t\tfmt.Printf("[%v] -> ", curr.Val)\n\t\tcurr = curr.Next\n\t}\n\tfmt.Println("nil")\n}\n\nfunc main() {\n\tlist := &LinkedList[int]{}\n\tlist.Add(10)\n\tlist.Add(20)\n\tlist.Add(30)\n\tlist.PrintAll()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [10] -> [20] -> [30] -> nil'}], 'under_the_hood': 'Указатель `tail` позволяет добавлять элементы в конец за $O(1)$.', 'pitfalls': 'Обновляйте `tail` при вставке первого элемента в пустой список.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова сложность поиска в связном списке?»\n**Ответ:** Время $O(N)$, память $O(1)$.'}, {'num': 64, 'title': 'Обобщённый кеш с ошибкой ErrNotFound', 'task': 'Обобщённый кеш `Cache[K comparable, V any]` на `map` + `Get`/`Set`/`Delete`. Ошибка при отсутствии ключа.', 'theory': 'Возврат `(V, error)` с ошибкой `ErrNotFound` идиоматичен для интеграции с цепочками обработки ошибок `fmt.Errorf`.', 'step_by_step': '1. Объявим `var ErrNotFound = errors.New("key not found")`.\n2. Реализуем `Cache[K comparable, V any]`.\n3. В `main` проверим `Get`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nvar ErrNotFound = errors.New("key not found")\n\ntype Cache[K comparable, V any] struct {\n\titems map[K]V\n}\n\nfunc NewCache[K comparable, V any]() *Cache[K, V] {\n\treturn &Cache[K, V]{items: make(map[K]V)}\n}\n\nfunc (c *Cache[K, V]) Set(k K, v V) {\n\tc.items[k] = v\n}\n\nfunc (c *Cache[K, V]) Get(k K) (V, error) {\n\tval, ok := c.items[k]\n\tif !ok {\n\t\tvar zero V\n\t\treturn zero, ErrNotFound\n\t}\n\treturn val, nil\n}\n\nfunc main() {\n\tc := NewCache[string, int]()\n\tc.Set("status", 200)\n\n\tval, _ := c.Get("status")\n\tfmt.Println("Status:", val)\n\n\t_, err := c.Get("missing")\n\tif errors.Is(err, ErrNotFound) {\n\t\tfmt.Println("Ошибка обработана: ключ отсутствует")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Status: 200\n# Ошибка обработана: ключ отсутствует'}], 'under_the_hood': '`errors.Is` сравнивает указатель на глобальную ошибку.', 'pitfalls': 'Возвращайте `var zero V` при ошибке, не пытаясь вернуть `nil`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда предпочесть (V, bool), а когда (V, error)?»\n**Ответ:** `(V, bool)` для быстрого in-memory кэша (0 аллокаций), `(V, error)` для распределенных систем (Redis/сеть).'}, {'num': 65, 'title': 'Монадический Result[T] в стиле Rust/Scala', 'task': 'Реализуй `Result[T any]` — тип, хранящий либо значение, либо ошибку. Методы: `IsOk() bool`, `IsErr() bool`, `Unwrap() T`, `UnwrapOr(default T) T`, `Map(fn func(T) T) Result[T]`, `FlatMap(fn func(T) Result[T]) Result[T]`.', 'theory': '`Result[T]` инкапсулирует результат успешного вычисления или ошибку, предоставляя методы `Map` и `UnwrapOr`.', 'step_by_step': '1. Объявим `type Result[T any] struct { value T; err error }`.\n2. Реализуем `Ok`, `Err`, `IsOk`, `Unwrap`, `UnwrapOr`, `Map`.\n3. В `main` построим цепочку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype Result[T any] struct {\n\tvalue T\n\terr   error\n}\n\nfunc Ok[T any](v T) Result[T]     { return Result[T]{value: v} }\nfunc Err[T any](e error) Result[T] { return Result[T]{err: e} }\n\nfunc (r Result[T]) IsOk() bool  { return r.err == nil }\nfunc (r Result[T]) Unwrap() T   { return r.value }\nfunc (r Result[T]) UnwrapOr(def T) T {\n\tif r.err != nil {\n\t\treturn def\n\t}\n\treturn r.value\n}\n\nfunc (r Result[T]) Map(fn func(T) T) Result[T] {\n\tif r.err != nil {\n\t\treturn r\n\t}\n\treturn Ok(fn(r.value))\n}\n\nfunc divide(a, b int) Result[int] {\n\tif b == 0 {\n\t\treturn Err[int](errors.New("деление на 0"))\n\t}\n\treturn Ok(a / b)\n}\n\nfunc main() {\n\tres1 := divide(100, 2).Map(func(v int) int { return v + 10 })\n\tfmt.Println("res1:", res1.Unwrap())\n\n\tres2 := divide(100, 0).Map(func(v int) int { return v + 10 })\n\tfmt.Println("res2 fallback:", res2.UnwrapOr(-1))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# res1: 60\n# res2 fallback: -1'}], 'under_the_hood': '`Result[T]` передается на стеке по значению без аллокаций в куче.', 'pitfalls': 'В Go стандартный `if err != nil` остается нормой сообщества.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go не приняли Result[T] в стандартную библиотеку?»\n**Ответ:** Явный императивный поток `if err != nil` проще для статического анализа и не провоцирует скрытых паник.'}, {'num': 66, 'title': 'Ограничение методов в Go: запрет generic-методов на структурах', 'task': '**Сюрприз дженериков (Ограничение на методы)**: Попытайся добавить в свой `Stack[T]` новый метод, который принимает свой собственный, независимый generic-параметр `func (s *Stack[T]) Map[U any](fn func(T) U) Stack[U]`. Убедись, что Go **не разрешает** generic-методы на структурах (только функции могут вводить новые параметры типов).', 'theory': 'В Go методы структур НЕ могут объявлять собственные новые параметры типов `[U any]`. Для таких операций используются отдельные функции верхнего уровня `MapStack[T, U any]`.', 'step_by_step': '1. Объявим `type Stack[T any] struct { items []T }`.\n2. Напишем функцию `MapStack[T, U any](s *Stack[T], fn func(T) U) *Stack[U]`.\n3. В `main` преобразуем стек чисел в стек строк.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"strconv"\n)\n\ntype Stack[T any] struct {\n\titems []T\n}\n\nfunc (s *Stack[T]) Push(v T) {\n\ts.items = append(s.items, v)\n}\n\nfunc (s *Stack[T]) Items() []T {\n\treturn s.items\n}\n\n// Отдельная generic-функция вместо запрещенного метода:\nfunc MapStack[T, U any](s *Stack[T], fn func(T) U) *Stack[U] {\n\tres := &Stack[U]{items: make([]U, len(s.items))}\n\tfor i, v := range s.items {\n\t\tres.items[i] = fn(v)\n\t}\n\treturn res\n}\n\nfunc main() {\n\tintStack := &Stack[int]{}\n\tintStack.Push(10)\n\tintStack.Push(20)\n\n\tstrStack := MapStack(intStack, func(n int) string {\n\t\treturn "val=" + strconv.Itoa(n)\n\t})\n\tfmt.Println("Стек строк:", strStack.Items())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Стек строк: [val=10 val=20]'}], 'under_the_hood': 'Generic-методы сломали бы построение интерфейсных таблиц `itab` во время сборки.', 'pitfalls': 'Метод может использовать только параметры типа самой структуры `[T]`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go запретили параметризованные методы у структур?»\n**Ответ:** Разрешение generic-методов сломало бы компиляцию динамических интерфейсов (duck typing) без JIT-компилятора в рантайме.'}]
